/** Shared config references used by schema validators and plugin runtimes. */

const write = Symbol.for('cosmokit.volatile.write')

/** Recursively readonly data returned by a volatile config reference. */
export type VolatileSnapshot<T> = T extends object ? { readonly [K in keyof T]: VolatileSnapshot<T[K]> } : T

/** A stable reference; keep the reference, or capture its value for one operation only. */
export interface Volatile<T> {
  /** @returns the current immutable snapshot, including undefined for an absent value. */
  get(): VolatileSnapshot<T>
}

interface WritableVolatile extends Volatile<unknown> {
  [write](value: unknown): void
}

function snapshot(value: unknown, ancestors = new Set<object>()): unknown {
  if (typeof value === 'function') throw new TypeError('volatile config cannot contain functions')
  if (value === null || typeof value !== 'object') return value
  if (ancestors.has(value)) throw new TypeError('volatile config cannot contain cycles')
  ancestors.add(value)
  try {
    if (Array.isArray(value)) return Object.freeze(value.map(item => snapshot(item, ancestors)))
    if (Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) {
      throw new TypeError('volatile config objects must be plain objects or arrays')
    }
    return Object.freeze(Object.fromEntries(Object.entries(value).map(([key, item]) => [key, snapshot(item, ancestors)])))
  } finally {
    ancestors.delete(value)
  }
}

/**
 * Create a detached reference containing an immutable copy of the supplied data.
 * @param value - validated config data; class instances and functions are unsupported.
 * @returns a reference whose value is updated only by its owning runtime.
 */
export function createVolatile<T>(value: T): Volatile<T> {
  let current = snapshot(value)
  return Object.freeze({
    get: () => current,
    [write]: (value: unknown) => { current = value },
  }) as Volatile<T>
}

/**
 * Identify references across ESM/CJS copies of the shared library.
 * @param value - a parsed config value.
 * @returns whether the value implements the shared reference protocol.
 */
export function isVolatile(value: unknown): value is Volatile<unknown> {
  return typeof value === 'object' && value !== null && write in value
}

/**
 * Collect config references without descending into their snapshots or opaque objects.
 * @internal
 * @param value - parsed config; cyclic ordinary fields are visited once per path.
 * @returns references and their object-key paths, including an empty path for a root reference.
 */
export function volatileEntries(value: unknown): { path: string[]; ref: Volatile<unknown> }[] {
  const ancestors = new Set<object>()
  function visit(value: unknown, path: string[]): { path: string[]; ref: Volatile<unknown> }[] {
    if (isVolatile(value)) return [{ path, ref: value }]
    if (!value || typeof value !== 'object' || ancestors.has(value)) return []
    if (!Array.isArray(value) && Object.getPrototypeOf(value) !== Object.prototype && Object.getPrototypeOf(value) !== null) return []
    ancestors.add(value)
    try {
      return Object.entries(value).flatMap(([key, child]) => visit(child, [...path, key]))
    } finally {
      ancestors.delete(value)
    }
  }
  return visit(value, [])
}

/**
 * Commit an already validated immutable snapshot from another reference.
 * @internal
 * @param target - the owning plugin's stable reference.
 * @param source - a newly parsed candidate reference.
 */
export function updateVolatile(target: Volatile<unknown>, source: Volatile<unknown>): void {
  ;(target as WritableVolatile)[write](source.get())
}

import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';import vm from 'node:vm';
const write=Symbol.for('cosmokit.volatile.write');
async function verify(api,label){let count=0;const pass=()=>count++;
assert.deepEqual(Object.keys(api).sort(),['createVolatile','isVolatile','updateVolatile','volatileEntries']);for(const name of Object.keys(api)){assert.equal(api[name].name,name);assert.equal(api[name].length,name==='updateVolatile'?2:1);assert.equal(Object.hasOwn(api[name],'prototype'),true);}pass();
for(const value of [undefined,null,false,0,-0,NaN,Infinity,1n,'x',Symbol('value')]){const ref=api.createVolatile(value);assert.equal(ref.get(),value);assert.ok(Object.isFrozen(ref));assert.equal(api.isVolatile(ref),true);}pass();
const input={a:{b:1},list:[2,{c:3}]},ref=api.createVolatile(input),snap=ref.get();assert.notEqual(snap,input);assert.notEqual(snap.a,input.a);assert.notEqual(snap.list,input.list);assert.deepEqual(snap,input);for(const x of [snap,snap.a,snap.list,snap.list[1]])assert.ok(Object.isFrozen(x));input.a.b=9;input.list.push(8);assert.equal(snap.a.b,1);assert.equal(snap.list.length,2);pass();
assert.deepEqual(Reflect.ownKeys(ref),['get',write]);assert.equal(ref.get.name,'get');assert.equal(ref.get.length,0);assert.equal(ref[write].name,'[cosmokit.volatile.write]');assert.equal(ref[write].length,1);assert.equal(Object.hasOwn(ref.get,'prototype'),false);assert.equal(Object.hasOwn(ref[write],'prototype'),false);assert.throws(()=>Reflect.construct(ref.get,[]),TypeError);assert.throws(()=>Reflect.construct(ref[write],[]),TypeError);const get=ref.get;assert.equal(get.call({}),snap);pass();
const next=api.createVolatile({next:1});assert.equal(api.updateVolatile(ref,next),undefined);assert.equal(ref.get(),next.get());assert.equal(snap.a.b,1);assert.equal(get(),next.get());const other=api.createVolatile(8);assert.equal(other.get(),8);pass();
const opaque=new Proxy({},{get(){throw Error('opaque read')},getPrototypeOf(){throw Error('opaque proto')}});assert.equal(ref[write](opaque),undefined);assert.equal(ref.get(),opaque);const fn=()=>3;ref[write](fn);assert.equal(ref.get(),fn);pass();
for(const v of [()=>{},function(){},class A{}])assert.throws(()=>api.createVolatile(v),e=>e instanceof TypeError&&e.message==='volatile config cannot contain functions');assert.throws(()=>api.createVolatile({fn}),e=>e instanceof TypeError&&e.message==='volatile config cannot contain functions');pass();
const cycle={};cycle.self=cycle;assert.throws(()=>api.createVolatile(cycle),e=>e instanceof TypeError&&e.message==='volatile config cannot contain cycles');const arr=[];arr.push(arr);assert.throws(()=>api.createVolatile(arr),e=>e instanceof TypeError&&e.message==='volatile config cannot contain cycles');pass();
const shared={k:1},alias=api.createVolatile({a:shared,b:shared}).get();assert.deepEqual(alias,{a:{k:1},b:{k:1}});assert.notEqual(alias.a,alias.b);pass();
const plain=Object.create(null);plain.x=1;plain.__proto__={safe:2};const copied=api.createVolatile(plain).get();assert.equal(Object.getPrototypeOf(copied),Object.prototype);assert.ok(Object.hasOwn(copied,'__proto__'));assert.deepEqual(copied.__proto__,{safe:2});pass();
for(const v of [new Date(),new Map(),new Set(),/x/,new Number(1),Object.create({}),vm.runInNewContext('({a:1})')])assert.throws(()=>api.createVolatile(v),e=>e instanceof TypeError&&e.message==='volatile config objects must be plain objects or arrays');pass();
const sparse=[,1,,3];sparse.extra=7;const sparseSnap=api.createVolatile(sparse).get();assert.equal(sparseSnap.length,4);assert.equal(0 in sparseSnap,false);assert.equal(2 in sparseSnap,false);assert.equal(sparseSnap.extra,undefined);const foreign=vm.runInNewContext('[1,2]');assert.deepEqual(Array.from(api.createVolatile(foreign).get()),[1,2]);pass();
const symbol=Symbol('skip');let reads=0;const source={get visible(){reads++;return {n:1}},[symbol]:fn};Object.defineProperty(source,'hidden',{value:fn});assert.deepEqual(api.createVolatile(source).get(),{visible:{n:1}});assert.equal(reads,1);pass();
for(const v of [undefined,null,0,'x',false,fn])assert.equal(api.isVolatile(v),false);assert.equal(api.isVolatile({[write]:0}),true);assert.equal(api.isVolatile(Object.create({[write]:null})),true);assert.equal(api.isVolatile({get(){return 1}}),false);pass();
const boom={};let key;assert.equal(api.isVolatile(new Proxy({},{has(t,k){key=k;return true},get(){throw boom}})),true);assert.equal(key,write);assert.throws(()=>api.isVolatile(new Proxy({},{has(){throw boom}})),e=>e===boom);const revoked=Proxy.revocable({},{});revoked.revoke();assert.throws(()=>api.isVolatile(revoked.proxy),TypeError);pass();
assert.deepEqual(api.volatileEntries(next),[{path:[],ref:next}]);assert.deepEqual(api.volatileEntries({outer:[next,,other]}),[{path:['outer','0'],ref:next},{path:['outer','2'],ref:other}]);pass();
const container={a:next};container.self=container;assert.deepEqual(api.volatileEntries({left:container,right:container}),[{path:['left','a'],ref:next},{path:['right','a'],ref:next}]);pass();
for(const value of [new Date(),new Map([['x',next]]),Object.assign(Object.create({}),{x:next}),vm.runInNewContext('({})'),fn,0,null])assert.deepEqual(api.volatileEntries(value),[]);const nullObj=Object.create(null);nullObj.x=next;assert.deepEqual(api.volatileEntries(nullObj),[{path:['x'],ref:next}]);pass();
const root={a:next,[symbol]:other};Object.defineProperty(root,'hidden',{value:other});assert.deepEqual(api.volatileEntries(root),[{path:['a'],ref:next}]);const extra=[];extra.z=next;assert.deepEqual(api.volatileEntries(extra),[{path:['z'],ref:next}]);pass();
let events=[];const target={get [write](){events.push('writer');return function(v){assert.equal(this,target);assert.equal(arguments.length,1);events.push('write');assert.equal(v,opaque);return boom}}},candidate={get get(){events.push('getter');return function(){assert.equal(this,candidate);assert.equal(arguments.length,0);events.push('get');return opaque}}};assert.equal(api.updateVolatile(target,candidate),undefined);assert.deepEqual(events,['writer','getter','get','write']);pass();
events=[];assert.throws(()=>api.updateVolatile({get [write](){throw boom}},candidate),e=>e===boom);assert.deepEqual(events,[]);events=[];assert.throws(()=>api.updateVolatile({[write]:null},candidate),TypeError);assert.deepEqual(events,['getter','get']);assert.throws(()=>api.updateVolatile(target,{get(){throw boom}}),e=>e===boom);pass();
const setDesc=Object.getOwnPropertyDescriptor(globalThis,'Set'),SetReal=globalThis.Set;events=[];class TraceSet extends SetReal{constructor(){super();events.push('new')}has(v){events.push('has');return super.has(v)}add(v){events.push('add');return super.add(v)}delete(v){events.push('delete');return super.delete(v)}}
try{globalThis.Set=TraceSet;const bad={get x(){events.push('read');throw boom}};assert.throws(()=>api.createVolatile(bad),e=>e===boom);assert.deepEqual(events,['new','has','add','read','delete']);events=[];assert.equal(api.createVolatile(1).get(),1);assert.deepEqual(events,['new']);events=[];assert.throws(()=>api.volatileEntries(bad),e=>e===boom);assert.deepEqual(events,['new','has','add','read','delete']);}finally{Reflect.defineProperty(globalThis,'Set',setDesc);}pass();
let cb;const customized=[1];customized.map=function(fn){assert.equal(this,customized);cb=fn;assert.equal(fn.name,'');assert.equal(fn.length,1);return {custom:1}};assert.deepEqual(api.createVolatile(customized).get(),{custom:1});assert.equal(cb(2),2);assert.deepEqual(cb({k:3}),{k:3});pass();
let captured;const entries=Object.getOwnPropertyDescriptor(Object,'entries');try{Object.entries=function(value){if(value===source)return {map(fn){captured=fn;assert.equal(fn.length,1);return [['custom',1]]}};return entries.value(value)};assert.deepEqual(api.createVolatile(source).get(),{custom:1});assert.deepEqual(captured(['x',{k:1}]),['x',{k:1}]);assert.equal(Object.hasOwn(captured,'prototype'),false);}finally{Reflect.defineProperty(Object,'entries',entries);}pass();
const descriptors=['getPrototypeOf','freeze','fromEntries'].map(name=>[name,Object.getOwnPropertyDescriptor(Object,name)]);try{Object.getPrototypeOf=()=>{throw boom};assert.throws(()=>api.createVolatile({}),e=>e===boom);}finally{for(const [name,desc] of descriptors)Reflect.defineProperty(Object,name,desc);}pass();
try{Object.freeze=function(v){if(Array.isArray(v))return opaque;return descriptors.find(([n])=>n==='freeze')[1].value(v)};assert.equal(api.createVolatile([1]).get(),opaque);}finally{for(const [name,desc] of descriptors)Reflect.defineProperty(Object,name,desc);}pass();
let n=0;const changing=new Proxy({},{getPrototypeOf(){n++;return n===1?Object.create(null):null}});assert.deepEqual(api.createVolatile(changing).get(),{});assert.equal(n,2);pass();
const proxyArray=new Proxy([],{get(t,k){if(k==='map')throw boom;return Reflect.get(t,k)},getPrototypeOf(){throw Error('should bypass proto')}});assert.throws(()=>api.createVolatile(proxyArray),e=>e===boom);pass();
const thenable={get then(){throw boom}};assert.equal(api.updateVolatile({[write](x){assert.equal(x,thenable);return thenable}},{get(){return thenable}}),undefined);pass();
const retained=api.createVolatile(0);for(let i=0;i<2000;i++){const fresh=api.createVolatile({i});api.updateVolatile(retained,fresh);assert.equal(retained.get(),fresh.get());assert.deepEqual(api.volatileEntries({ref:retained}),[{path:['ref'],ref:retained}]);}pass();
assert.equal(count,30);console.log(label+': 30 complete volatile runtime contract groups passed.');}
const baseline=await import('./volatile-baseline.mjs');await verify(baseline,'actual TypeScript volatile baseline');
if(process.argv[2]){const native=await import(pathToFileURL(process.argv[2]).href);const grants={get Object(){return globalThis.Object},get Array(){return globalThis.Array},get Set(){return globalThis.Set},get TypeError(){return globalThis.TypeError},get Symbol(){return globalThis.Symbol}};const api=native.instantiateMithrilNative(grants);await verify(api,'Mithril volatile candidate');const cross=api.createVolatile({x:1});assert.equal(baseline.isVolatile(cross),true);assert.equal(api.isVolatile(baseline.createVolatile(2)),true);const source=baseline.createVolatile(3);api.updateVolatile(cross,source);assert.equal(cross.get(),source.get());const original=Symbol.for;try{Symbol.for=()=>{throw Error('module symbol must be cached')};assert.equal(api.isVolatile(cross),true);assert.equal(api.createVolatile(0).get(),0);}finally{Symbol.for=original;}const second=native.instantiateMithrilNative(grants);assert.notEqual(second.createVolatile,api.createVolatile);console.log('Cross-copy symbol protocol and module-instance initialization passed.');}
